import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_01_control_planes.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_02_roles.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_03_managed.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_04_data.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_05_supply_chain.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_06_observability.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_07_maturity.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_08_accountability.png",g=JSON.parse('{"title":"企业如何安全用 Codex：身份、策略、审计与规模化治理","description":"个人使用 Codex 时，边界通常是一台电脑和一个仓库；企业使用时，同时涉及 ChatGPT Workspace、本地运行时、Codex Cloud、Platform API、Plugins、Connectors 和源代码系统。官方 Administration 文档强调，这些控制面彼此关联却不互相","frontmatter":{"title":"企业如何安全用 Codex：身份、策略、审计与规模化治理","description":"个人使用 Codex 时，边界通常是一台电脑和一个仓库；企业使用时，同时涉及 ChatGPT Workspace、本地运行时、Codex Cloud、Platform API、Plugins、Connectors 和源代码系统。官方 Administration 文档强调，这些控制面彼此关联却不互相","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":6,"source":"2026-08-10/ai_codex_official_10_enterprise_governance.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_10_01_control_planes.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"企业如何安全用 Codex：身份、策略、审计与规模化治理"}],["meta",{"property":"og:description","content":"个人使用 Codex 时，边界通常是一台电脑和一个仓库；企业使用时，同时涉及 ChatGPT Workspace、本地运行时、Codex Cloud、Platform API、Plugins、Connectors 和源代码系统。官方 Administration 文档强调，这些控制面彼此关联却不互相"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_01_control_planes.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"企业如何安全用 Codex：身份、策略、审计与规模化治理"}],["meta",{"name":"twitter:description","content":"个人使用 Codex 时，边界通常是一台电脑和一个仓库；企业使用时，同时涉及 ChatGPT Workspace、本地运行时、Codex Cloud、Platform API、Plugins、Connectors 和源代码系统。官方 Administration 文档强调，这些控制面彼此关联却不互相"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_10_01_control_planes.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-10-enterprise-governance.md","filePath":"archive/ai-codex-official-10-enterprise-governance.md","lastUpdated":null}'),_={name:"archive/ai-codex-official-10-enterprise-governance.md"};function m(u,a,f,b,x,P){return t(),o("div",null,[...a[0]||(a[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="企业如何安全用-codex-身份、策略、审计与规模化治理" tabindex="-1">企业如何安全用 Codex：身份、策略、审计与规模化治理 <a class="header-anchor" href="#企业如何安全用-codex-身份、策略、审计与规模化治理" aria-label="Permalink to &quot;企业如何安全用 Codex：身份、策略、审计与规模化治理&quot;">​</a></h1><p>个人使用 Codex 时，边界通常是一台电脑和一个仓库；企业使用时，同时涉及 ChatGPT Workspace、本地运行时、Codex Cloud、Platform API、Plugins、Connectors 和源代码系统。官方 Administration 文档强调，这些控制面彼此关联却不互相替代。</p><h2 id="一、企业先画清六个控制面" tabindex="-1">一、企业先画清六个控制面 <a class="header-anchor" href="#一、企业先画清六个控制面" aria-label="Permalink to &quot;一、企业先画清六个控制面&quot;">​</a></h2><h3 id="_1-1-workspace-身份与角色" tabindex="-1">1.1 Workspace 身份与角色 <a class="header-anchor" href="#_1-1-workspace-身份与角色" aria-label="Permalink to &quot;1.1 Workspace 身份与角色&quot;">​</a></h3><p>成员、席位、组和角色决定用户可以访问哪些 Workspace 能力。管理员角色只授予真正负责管理的人。</p><h3 id="_1-2-本地运行时策略" tabindex="-1">1.2 本地运行时策略 <a class="header-anchor" href="#_1-2-本地运行时策略" aria-label="Permalink to &quot;1.2 本地运行时策略&quot;">​</a></h3><p>桌面端、CLI 和 IDE 在设备上执行命令时，受到 Permission Profile、Sandbox、Approval、Feature 和受管配置约束。</p><h3 id="_1-3-codex-cloud-与仓库连接" tabindex="-1">1.3 Codex Cloud 与仓库连接 <a class="header-anchor" href="#_1-3-codex-cloud-与仓库连接" aria-label="Permalink to &quot;1.3 Codex Cloud 与仓库连接&quot;">​</a></h3><p>云端环境、Secrets、网络和源代码平台权限共同决定远程任务能访问什么。Workspace 身份不会绕过 GitHub 保护规则。</p><h3 id="_1-4-platform-api" tabindex="-1">1.4 Platform API <a class="header-anchor" href="#_1-4-platform-api" aria-label="Permalink to &quot;1.4 Platform API&quot;">​</a></h3><p>API 组织、Project、Key、配额与账单属于独立边界。ChatGPT 方案不自动授予任意 API 权限。</p><h3 id="_1-5-plugin-与-connector" tabindex="-1">1.5 Plugin 与 Connector <a class="header-anchor" href="#_1-5-plugin-与-connector" aria-label="Permalink to &quot;1.5 Plugin 与 Connector&quot;">​</a></h3><p>Workspace 控制能力是否可用，连接系统继续控制真实数据与动作。安装插件不代表批准所有外部副作用。</p><h3 id="_1-6-analytics-与-compliance" tabindex="-1">1.6 Analytics 与 Compliance <a class="header-anchor" href="#_1-6-analytics-与-compliance" aria-label="Permalink to &quot;1.6 Analytics 与 Compliance&quot;">​</a></h3><p>分析采用情况和导出审计事件服务不同目标，需要不同权限与下游保护。</p><p><img src="'+r+'" alt="图 1：身份、运行时、Cloud、API、插件与审计六个控制面"></p><h2 id="二、角色与权限必须分层验证" tabindex="-1">二、角色与权限必须分层验证 <a class="header-anchor" href="#二、角色与权限必须分层验证" aria-label="Permalink to &quot;二、角色与权限必须分层验证&quot;">​</a></h2><h3 id="_2-1-同一个人拥有多种系统身份" tabindex="-1">2.1 同一个人拥有多种系统身份 <a class="header-anchor" href="#_2-1-同一个人拥有多种系统身份" aria-label="Permalink to &quot;2.1 同一个人拥有多种系统身份&quot;">​</a></h3><p>工程师可能同时是 Workspace 成员、GitHub 写入者、API Project 使用者和本机管理员。每个身份都有独立审批者和生命周期。</p><h3 id="_2-2-最小权限围绕工作流分配" tabindex="-1">2.2 最小权限围绕工作流分配 <a class="header-anchor" href="#_2-2-最小权限围绕工作流分配" aria-label="Permalink to &quot;2.2 最小权限围绕工作流分配&quot;">​</a></h3><p>代码只读 Review、生成补丁、Cloud 执行、评论 Pull Request 和生产发布是不同阶段，不应共用最高权限。</p><h3 id="_2-3-代表用户测试比配置截图可靠" tabindex="-1">2.3 代表用户测试比配置截图可靠 <a class="header-anchor" href="#_2-3-代表用户测试比配置截图可靠" aria-label="Permalink to &quot;2.3 代表用户测试比配置截图可靠&quot;">​</a></h3><p>管理员应使用具有目标权限的真实成员验证登录、模型可见性、仓库访问、本地策略和连接器动作。页面显示“已启用”不等于端到端生效。</p><p><img src="'+n+'" alt="图 2：Workspace、本地、API 与源系统权限独立校验"></p><h2 id="三、managed-configuration-约束运行时" tabindex="-1">三、Managed Configuration 约束运行时 <a class="header-anchor" href="#三、managed-configuration-约束运行时" aria-label="Permalink to &quot;三、Managed Configuration 约束运行时&quot;">​</a></h2><h3 id="_3-1-默认值与强制要求分离" tabindex="-1">3.1 默认值与强制要求分离 <a class="header-anchor" href="#_3-1-默认值与强制要求分离" aria-label="Permalink to &quot;3.1 默认值与强制要求分离&quot;">​</a></h3><p>默认配置提高一致性，<code>requirements.toml</code> 等受管要求限制成员不能超出的模型、权限和功能边界。</p><h3 id="_3-2-仓库配置不能授予组织权限" tabindex="-1">3.2 仓库配置不能授予组织权限 <a class="header-anchor" href="#_3-2-仓库配置不能授予组织权限" aria-label="Permalink to &quot;3.2 仓库配置不能授予组织权限&quot;">​</a></h3><p><code>.codex</code>、<code>.agents</code>、Rules 和 Skills 适合共享项目工作流，但不能授予 Workspace、API 或源系统访问。</p><h3 id="_3-3-客户端版本需要治理" tabindex="-1">3.3 客户端版本需要治理 <a class="header-anchor" href="#_3-3-客户端版本需要治理" aria-label="Permalink to &quot;3.3 客户端版本需要治理&quot;">​</a></h3><p>新配置能力可能要求最低版本。组织需要分批更新、兼容期、验证和撤回路径，避免旧客户端静默忽略策略。</p><p><img src="'+l+'" alt="图 3：组织默认、强制要求、客户端应用与运行检查"></p><h2 id="四、数据治理覆盖输入与输出" tabindex="-1">四、数据治理覆盖输入与输出 <a class="header-anchor" href="#四、数据治理覆盖输入与输出" aria-label="Permalink to &quot;四、数据治理覆盖输入与输出&quot;">​</a></h2><h3 id="_4-1-数据分类决定可用能力" tabindex="-1">4.1 数据分类决定可用能力 <a class="header-anchor" href="#_4-1-数据分类决定可用能力" aria-label="Permalink to &quot;4.1 数据分类决定可用能力&quot;">​</a></h3><p>公开代码、内部代码、客户数据和受监管信息采用不同模型、连接器、网络和日志策略。</p><h3 id="_4-2-secrets-使用短期受控路径" tabindex="-1">4.2 Secrets 使用短期受控路径 <a class="header-anchor" href="#_4-2-secrets-使用短期受控路径" aria-label="Permalink to &quot;4.2 Secrets 使用短期受控路径&quot;">​</a></h3><p>凭据不进入 Prompt、源码和普通日志。云端设置阶段、本地秘密管理和短期 Token 减少暴露面。</p><h3 id="_4-3-输出同样可能敏感" tabindex="-1">4.3 输出同样可能敏感 <a class="header-anchor" href="#_4-3-输出同样可能敏感" aria-label="Permalink to &quot;4.3 输出同样可能敏感&quot;">​</a></h3><p>Diff、任务摘要、聊天回复、Analytics 导出和 Compliance 记录都可能包含内部信息，需要访问、保留和删除策略。</p><p><img src="'+c+'" alt="图 4：数据分类、运行边界、输出控制与保留策略"></p><h2 id="五、插件与-skills-属于供应链" tabindex="-1">五、插件与 Skills 属于供应链 <a class="header-anchor" href="#五、插件与-skills-属于供应链" aria-label="Permalink to &quot;五、插件与 Skills 属于供应链&quot;">​</a></h2><h3 id="_5-1-准入审查来源和能力" tabindex="-1">5.1 准入审查来源和能力 <a class="header-anchor" href="#_5-1-准入审查来源和能力" aria-label="Permalink to &quot;5.1 准入审查来源和能力&quot;">​</a></h3><p>确认负责人、目标用户、Skills、MCP、Hooks、Connector、数据和外部动作。</p><h3 id="_5-2-更新必须重新评估权限" tabindex="-1">5.2 更新必须重新评估权限 <a class="header-anchor" href="#_5-2-更新必须重新评估权限" aria-label="Permalink to &quot;5.2 更新必须重新评估权限&quot;">​</a></h3><p>新版本可能新增工具或改变数据流。版本升级不能只看功能，需要比较能力清单。</p><h3 id="_5-3-每项能力都要能撤销" tabindex="-1">5.3 每项能力都要能撤销 <a class="header-anchor" href="#_5-3-每项能力都要能撤销" aria-label="Permalink to &quot;5.3 每项能力都要能撤销&quot;">​</a></h3><p>记录复查日期、停用方式和事故负责人。源失联、权限扩大或协议变化时能够快速移除。</p><p><img src="'+s+'" alt="图 5：能力准入、版本复查、运行观测与撤销闭环"></p><h2 id="六、analytics-与-compliance-回答不同问题" tabindex="-1">六、Analytics 与 Compliance 回答不同问题 <a class="header-anchor" href="#六、analytics-与-compliance-回答不同问题" aria-label="Permalink to &quot;六、Analytics 与 Compliance 回答不同问题&quot;">​</a></h2><h3 id="_6-1-analytics-观察采用和活动" tabindex="-1">6.1 Analytics 观察采用和活动 <a class="header-anchor" href="#_6-1-analytics-观察采用和活动" aria-label="Permalink to &quot;6.1 Analytics 观察采用和活动&quot;">​</a></h3><p>Workspace Analytics 与 Codex Analytics 适合交互查看趋势，Analytics API 适合把聚合指标接入数据仓库与 BI。</p><h3 id="_6-2-compliance-支持审计和调查" tabindex="-1">6.2 Compliance 支持审计和调查 <a class="header-anchor" href="#_6-2-compliance-支持审计和调查" aria-label="Permalink to &quot;6.2 Compliance 支持审计和调查&quot;">​</a></h3><p>Compliance API 面向安全、法务和治理记录，不是生产力排行榜。字段、保留和访问要求以认证后的当前 API Reference 为准。</p><h3 id="_6-3-成本控制不替代安全治理" tabindex="-1">6.3 成本控制不替代安全治理 <a class="header-anchor" href="#_6-3-成本控制不替代安全治理" aria-label="Permalink to &quot;6.3 成本控制不替代安全治理&quot;">​</a></h3><p>Workspace Credits、使用限额和 Platform API 账单属于不同体系。限制花费不会自动限制文件、仓库和生产动作权限。</p><p><img src="'+d+'" alt="图 6：活动事件分别流向分析指标与合规审计"></p><h2 id="七、从试点到规模化逐级推进" tabindex="-1">七、从试点到规模化逐级推进 <a class="header-anchor" href="#七、从试点到规模化逐级推进" aria-label="Permalink to &quot;七、从试点到规模化逐级推进&quot;">​</a></h2><h3 id="_7-1-试点阶段验证低风险真实任务" tabindex="-1">7.1 试点阶段验证低风险真实任务 <a class="header-anchor" href="#_7-1-试点阶段验证低风险真实任务" aria-label="Permalink to &quot;7.1 试点阶段验证低风险真实任务&quot;">​</a></h3><p>选择测试完备、数据风险低的仓库，跑通身份、项目规则、权限、Review 和支持流程。</p><h3 id="_7-2-团队阶段固化工作方式" tabindex="-1">7.2 团队阶段固化工作方式 <a class="header-anchor" href="#_7-2-团队阶段固化工作方式" aria-label="Permalink to &quot;7.2 团队阶段固化工作方式&quot;">​</a></h3><p>统一 <code>AGENTS.md</code>、验证命令、Review 清单和能力负责人，让成功不依赖少数高手。</p><h3 id="_7-3-平台阶段连接系统" tabindex="-1">7.3 平台阶段连接系统 <a class="header-anchor" href="#_7-3-平台阶段连接系统" aria-label="Permalink to &quot;7.3 平台阶段连接系统&quot;">​</a></h3><p>单仓库流程稳定后再接入 Cloud、CI、Slack、Linear、SDK 与 MCP，并补齐身份、幂等和审计。</p><h3 id="_7-4-持续阶段用证据调整" tabindex="-1">7.4 持续阶段用证据调整 <a class="header-anchor" href="#_7-4-持续阶段用证据调整" aria-label="Permalink to &quot;7.4 持续阶段用证据调整&quot;">​</a></h3><p>定期复查访问、插件、客户端版本、成本、支持问题、回归缺陷和高风险事件。衡量可信交付，不以生成代码行数作为目标。</p><p><img src="'+h+'" alt="图 7：个人试点、团队规范、平台治理与持续改进"></p><h2 id="八、治理的最终产物是责任链" tabindex="-1">八、治理的最终产物是责任链 <a class="header-anchor" href="#八、治理的最终产物是责任链" aria-label="Permalink to &quot;八、治理的最终产物是责任链&quot;">​</a></h2><p>企业需要能够回答：谁在什么身份下，对哪个仓库和数据，使用了什么模型与工具，经过哪些批准，产生了什么外部状态，并由什么证据完成验收。只有责任链稳定，Codex 才能从个人效率工具变成组织能力。</p><p><img src="'+p+'" alt="图 8：身份、任务、工具、批准、验证与责任形成治理闭环"></p><h2 id="九、官方参考资料" tabindex="-1">九、官方参考资料 <a class="header-anchor" href="#九、官方参考资料" aria-label="Permalink to &quot;九、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/administration" target="_blank" rel="noreferrer">OpenAI Docs：Administration</a></p><p><a href="https://learn.chatgpt.com/docs/enterprise/admin-setup" target="_blank" rel="noreferrer">OpenAI Docs：Admin rollout</a></p><p><a href="https://learn.chatgpt.com/docs/enterprise/managed-configuration" target="_blank" rel="noreferrer">OpenAI Docs：Managed configuration</a></p><p><a href="https://learn.chatgpt.com/docs/enterprise/governance" target="_blank" rel="noreferrer">OpenAI Docs：Governance</a></p>',75)])])}const k=e(_,[["render",m]]);export{g as __pageData,k as default};
